    * The HTTPS endpoint URL that will receive the webhook deliveries.
    */
    // @ApiMember(Description="The HTTPS endpoint URL that will receive the webhook deliveries.", IsRequired=true)
    public var endpointUrl:String?

    /**
    * The event names this destination subscribes to. Empty subscribes to none.
    */
    // @ApiMember(Description="The event names this destination subscribes to. Empty subscribes to none.")
    public var selectedEvents:[String] = []

    /**
    * Destination-specific static headers sent with every delivery to this destination. These win over the integration-wide extra headers on duplicate keys.
    */
    // @ApiMember(Description="Destination-specific static headers sent with every delivery to this destination. These win over the integration-wide extra headers on duplicate keys.")
    public var extraHeaders:[String:String]?

    /**
    * Whether this destination is enabled for delivery. Defaults to true.
    */
    // @ApiMember(Description="Whether this destination is enabled for delivery. Defaults to true.")
    public var isEnabled:Bool?

    required public init(){ super.init() }

    private enum CodingKeys : String, CodingKey {
        case destinationId
        case destinationName
        case endpointUrl
        case selectedEvents
        case extraHeaders
        case isEnabled
    }

    required public init(from decoder: Decoder) throws {
        try super.init(from: decoder)
        let container = try decoder.container(keyedBy: CodingKeys.self)
        destinationId = try container.decodeIfPresent(String.self, forKey: .destinationId)
        destinationName = try container.decodeIfPresent(String.self, forKey: .destinationName)
        endpointUrl = try container.decodeIfPresent(String.self, forKey: .endpointUrl)
        selectedEvents = try container.decodeIfPresent([String].self, forKey: .selectedEvents) ?? []
        extraHeaders = try container.decodeIfPresent([String:String].self, forKey: .extraHeaders) ?? [:]
        isEnabled = try container.decodeIfPresent(Bool.self, forKey: .isEnabled)
    }

    public override func encode(to encoder: Encoder) throws {
        try super.encode(to: encoder)
        var container = encoder.container(keyedBy: CodingKeys.self)
        if destinationId != nil { try container.encode(destinationId, forKey: .destinationId) }
        if destinationName != nil { try container.encode(destinationName, forKey: .destinationName) }
        if endpointUrl != nil { try container.encode(endpointUrl, forKey: .endpointUrl) }
        if selectedEvents.count > 0 { try container.encode(selectedEvents, forKey: .selectedEvents) }
        if extraHeaders != nil { try container.encode(extraHeaders, forKey: .extraHeaders) }
        if isEnabled != nil { try container.encode(isEnabled, forKey: .isEnabled) }
    }
}

